'use strict';
window.collectionUI=(()=>{
 let data={items:[],lists:[],events:[],counts:{}},accountData={authenticated:false},selectedList=null,loaded=false,refreshJob=0,searchSeq=0,catalogTarget=null,activeWine=null,authMode='login',authMerge=null;
 const $c=id=>document.getElementById(id), e=escapeHTML;
 async function request(path,body){const response=await fetch('/api/product/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});let result;try{result=await response.json();}catch{throw Error('Не удалось получить ответ. Попробуйте ещё раз.');}if(!response.ok){const error=Error(typeof result.detail==='string'?result.detail:'Не удалось сохранить изменения');error.detail=result.detail;error.status=response.status;throw error;}return result;}
 function errorAt(root,error){const el=root.querySelector('.form-error');if(el){el.textContent=error.message;el.hidden=false;}else notice(error.message);}
 async function busy(button,fn,root){if(button.disabled)return;button.disabled=true;try{await fn();}catch(error){errorAt(root||button.parentElement,error);}finally{button.disabled=false;}}
 function modal(id){if(!$c(id).open)openDialog(id);}
 function closeAll(){document.querySelectorAll('dialog[open]:not(#age-dialog)').forEach(closeDialog);}
 function plural(n,one,few,many){const a=n%100,b=n%10;return n+' '+(a>=11&&a<=14?many:b===1?one:b>=2&&b<=4?few:many);}
 function word(n,a,b,c){return plural(n,a,b,c).slice(String(n).length+1);}
 function date(value){return new Date(value*1000).toLocaleDateString('ru-RU',{day:'numeric',month:'short'});}
 function currentItem(slug){return data.items.find(w=>w.slug===slug);}
 async function refresh(){const own=++refreshJob;try{await initPromise;const [snapshot,profile]=await Promise.all([request('collection'),request('account')]);if(own!==refreshJob)return;data=snapshot;accountData=profile;syncAccountControls(profile);loaded=true;productData.preferences=Object.fromEntries(data.items.map(w=>[w.slug,{favorite:w.favorite,rating:w.rating}]));productData.collection=data.items.filter(w=>w.favorite||w.rating);store.set('wine-product',productData);$c('cellar-error').hidden=true;render();if(currentWine)attach(currentWine);return snapshot;}catch(error){if(own!==refreshJob)return;$c('cellar-error').hidden=false;$c('cellar-error').textContent='Не удалось обновить коллекцию. '+error.message;}}
 function render(){
  if(!$c('cellar-summary'))return;
  $c('cellar-summary').textContent=data.counts.all?`${plural(data.counts.all,'вино','вина','вин')} в вашей истории · ${plural(data.counts.bottles,'бутылка','бутылки','бутылок')} дома`:'Вина, к которым хочется вернуться.';
  $c('cellar-guest-note').hidden=accountData.authenticated;
  const lists=$c('cellar-lists');lists.innerHTML=data.lists.map(l=>`<button class="list-cover ${selectedList===l.id?'selected':''}" data-list="${e(l.id)}"><span class="list-cover-icon" aria-hidden="true">${icons('glass')}</span><span><strong>${e(l.name)}</strong><small>${l.members.length}${l.size?' / '+l.size:''} вин${l.goal?' · '+e(l.goal):''}</small></span></button>`).join('')+'<button class="list-cover list-new" id="new-collection-list"><span class="list-cover-icon" aria-hidden="true">+</span><span><strong>Новая коллекция</strong><small>Для повода или настроения</small></span></button>';
  lists.querySelectorAll('[data-list]').forEach(button=>button.onclick=()=>{selectedList=button.dataset.list;render();});$c('new-collection-list').onclick=()=>modal('list-create-dialog');
  const list=data.lists.find(l=>l.id===selectedList);if(!list)selectedList=null;
  const heading=$c('cellar-list-heading');heading.hidden=!list;
  if(list){heading.innerHTML=`<div><button class="text-button" id="all-collection">← Все вина</button><h2>${e(list.name)}</h2><p>${list.size?`${list.members.length} из ${list.size} мест заполнено`:'Ваша подборка'}${list.goal?' · '+e(list.goal):''}</p></div><div class="list-tools"><button id="list-add-wine" class="text-button">+ Добавить</button><button id="list-rename" class="text-button">Переименовать</button><button id="list-delete" class="text-button">Удалить коллекцию</button></div>`;$c('all-collection').onclick=()=>{selectedList=null;render();};$c('list-add-wine').onclick=()=>openCatalog({id:list.id});$c('list-rename').onclick=()=>renameList(list);$c('list-delete').onclick=()=>deleteList(list);}
  let wines=data.items.filter(w=>!list||w.lists.includes(list.id));
  const q=$c('cellar-query').value.toLocaleLowerCase('ru').trim(),color=$c('cellar-color').value.toLowerCase();
  if(q)wines=wines.filter(w=>[w.name,w.winery,w.grapes,w.note].join(' ').toLocaleLowerCase('ru').includes(q));if(color)wines=wines.filter(w=>w.category.toLowerCase().includes(color));
  wines.sort((a,b)=>b.updated-a.updated);
  const root=$c('collection-list');root.replaceChildren();
  for(const w of wines){const card=miniWine(w);card.classList.add('cellar-wine');if(list)card.style.order=String(list.members.find(m=>m.slug===w.slug)?.slot||0);const foot=document.createElement('div');foot.className='cellar-card-footer';foot.innerHTML=`<div class="wine-statuses">${w.favorite?'<span>Хочу попробовать</span>':''}${w.quantity?`<span>${w.quantity} бут. дома</span>`:''}${w.tried?'<span>Пробовал</span>':''}</div>${w.note?`<p class="cellar-note">${e(w.note)}</p>`:''}<button class="text-button">Мои записи <span aria-hidden="true">↗</span></button>`;foot.querySelector('button').onclick=()=>editWine(w);card.append(foot);root.append(card);}
  if(list?.size&&!q&&!color){const used=new Set(list.members.map(m=>m.slot));for(let slot=0;slot<list.size;slot++){if(used.has(slot))continue;const button=document.createElement('button');button.className='collection-slot';button.style.order=String(slot);button.innerHTML=`<span class="slot-number">${String(slot+1).padStart(2,'0')}</span><span class="slot-plus" aria-hidden="true">+</span><strong>Место для открытия</strong><small>Выберите вино</small>`;button.onclick=()=>openCatalog({id:list.id,slot});root.append(button);}}
  if(list)root.replaceChildren(...[...root.children].sort((a,b)=>Number(a.style.order)-Number(b.style.order)));
  if(!root.children.length){const title=q||color?'Таких вин пока нет':'У каждого вина — своя история';const copy=q||color?'Измените поиск или цвет.':'Начните со скана или найдите знакомое вино в каталоге.';root.innerHTML=`<div class="cellar-empty"><span class="empty-glass" aria-hidden="true">${icons('glass')}</span><h2>${title}</h2><p>${copy}</p><button class="cellar-primary" id="empty-add">${q||color?'Сбросить фильтры':'Выбрать вино'}</button></div>`;$c('empty-add').onclick=()=>{if(q||color){$c('cellar-query').value='';$c('cellar-color').value='';render();}else openCatalog();};}
 }
 function attach(w){const holder=document.querySelector('.portal-card-actions');if(!holder||w.preferences_available===false)return;let button=$c('collection-card-button');if(!button){button=document.createElement('button');button.id='collection-card-button';button.className='portal-save collection-card-button';holder.insertBefore(button,holder.firstChild);}const item=currentItem(w.slug);button.textContent=item?.quantity?'У меня · '+item.quantity+' бут.':'В коллекцию';button.onclick=()=>editWine(w);}
 async function editWine(w){await refresh();activeWine=w;paintWine();modal('collection-wine-dialog');}
 function paintWine(){
  const w=activeWine;if(!w)return;const item=currentItem(w.slug)||{lists:[]};const root=$c('collection-wine-content');
  root.innerHTML=`<div class="edit-wine-heading">${img(w)}<div><small>${e(w.winery)}</small><h2 id="collection-wine-title">${e(w.name)}</h2></div></div><form id="entry-note-form" class="cellar-form"><section class="entry-lists"><h3>В подборках</h3>${data.lists.length?data.lists.map(l=>`<label class="check-line"><input type="checkbox" data-entry-list="${e(l.id)}" ${item.lists.includes(l.id)?'checked':''}><span>${e(l.name)}<small>${e(l.goal||'Своя подборка')}</small></span></label>`).join(''):'<p>Создайте коллекцию — например, «К празднику».</p>'}</section><p class="form-error" role="alert" hidden></p><button class="cellar-primary" type="submit">Добавить вино</button></form>`;
  handleBrokenImages(root);
  $c('entry-note-form').onsubmit=ev=>{ev.preventDefault();const form=ev.currentTarget,inputs=[...form.querySelectorAll('[data-entry-list]')];busy(ev.submitter,async()=>{
   form.querySelector('.form-error').hidden=true;inputs.forEach(input=>input.disabled=true);
   try{for(const input of inputs){const selected=input.checked;if(selected===item.lists.includes(input.dataset.entryList))continue;await request('collection/lists/'+input.dataset.entryList,{action:selected?'add':'remove',slug:w.slug});}await refresh();paintWine();$c('entry-note-form').querySelector('button').focus({preventScroll:true});notice('Запись сохранена');}
   finally{inputs.forEach(input=>input.disabled=false);}
  },form);};
 }
 function openCatalog(target=null){catalogTarget=target;const list=data.lists.find(l=>l.id===target?.id);$c('catalog-title').textContent=list?'Вино в подборку':'Добавить вино';$c('catalog-context').textContent=list?list.name+(target.slot!==undefined?' · место '+(target.slot+1):''):'Найдите вино по названию, сорту или винодельне.';$c('wine-search').value='';modal('catalog-dialog');search();}
 async function search(){const own=++searchSeq,q=$c('wine-search').value.trim(),root=$c('search-results');root.hidden=false;root.innerHTML='<p class="catalog-loading">Ищем вина…</p>';try{const answer=q?await request('search?q='+encodeURIComponent(q)):await request('recommendations');if(own!==searchSeq)return;let items=answer.items;const list=data.lists.find(l=>l.id===catalogTarget?.id);if(list)items=items.filter(w=>!list.members.some(m=>m.slug===w.slug));root.replaceChildren();if(!items.length){root.innerHTML='<p class="catalog-loading">Ничего не нашли. Попробуйте другой сорт или название.</p>';return;}const label=document.createElement('p');label.className='catalog-result-label';label.textContent=q?'Найдено: '+items.length:'Из каталога для знакомства';root.append(label);for(const w of items){const row=document.createElement('article');row.className='catalog-option';row.innerHTML=`${img(w)}<div><h3>${e(w.name)}</h3><p>${e(w.winery)} · ${e(w.category)}</p><small>${e(w.grapes)}</small></div><button class="text-button">${catalogTarget?'Добавить':'Выбрать'} <span aria-hidden="true">↗</span></button>`;row.querySelector('button').onclick=()=>busy(row.querySelector('button'),async()=>{if(catalogTarget){await request('collection/lists/'+catalogTarget.id,{action:'add',slug:w.slug,slot:catalogTarget.slot});closeDialog($c('catalog-dialog'));await refresh();notice('Вино добавлено в подборку');}else{closeDialog($c('catalog-dialog'));await editWine(w);}},root);root.append(row);}handleBrokenImages(root);}catch(error){if(own===searchSeq)root.textContent=error.message;}}
 function confirmation(title,copy,action){const dialog=document.createElement('dialog');dialog.className='cellar-dialog';dialog.innerHTML=`<div class="dialog-head"><h2>${e(title)}</h2><button type="button" aria-label="Закрыть">${icons('close')}</button></div><p>${e(copy)}</p><p class="form-error" role="alert" hidden></p><div class="confirmation-actions"><button class="cellar-primary">Подтвердить</button><button class="text-button">Отмена</button></div>`;document.body.append(dialog);const close=()=>dialog.close();dialog.querySelector('.dialog-head button').onclick=close;dialog.querySelector('.confirmation-actions .text-button').onclick=close;dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');dialog.remove();});dialog.querySelector('.cellar-primary').onclick=ev=>busy(ev.currentTarget,async()=>{await action();close();},dialog);dialog.showModal();document.body.classList.add('modal-open');}
 function deleteList(list){confirmation('Удалить коллекцию?',`«${list.name}» исчезнет из списка. Статусы вин, бутылки, оценки и заметки сохранятся.`,async()=>{await request('collection/lists/'+list.id,{action:'delete'});selectedList=null;await refresh();});}
 function renameList(list){const dialog=document.createElement('dialog');dialog.className='cellar-dialog';dialog.innerHTML=`<div class="dialog-head"><h2>Название подборки</h2><button aria-label="Закрыть">${icons('close')}</button></div><form class="cellar-form"><label>Название<input name="name" maxlength="80" value="${e(list.name)}" required></label><p class="form-error" role="alert" hidden></p><button class="cellar-primary">Сохранить</button></form>`;document.body.append(dialog);dialog.querySelector('.dialog-head button').onclick=()=>dialog.close();dialog.onclose=()=>{document.body.classList.remove('modal-open');dialog.remove();};dialog.querySelector('form').onsubmit=ev=>{ev.preventDefault();busy(ev.submitter,async()=>{await request('collection/lists/'+list.id,{action:'rename',name:ev.target.elements.name.value});await refresh();dialog.close();},dialog);};dialog.showModal();document.body.classList.add('modal-open');}
 async function account(){await refresh();renderAccount();}
 function renderAccount(){
  const root=$c('account-content');if(accountData.authenticated){root.innerHTML=`<header class="account-heading"><span class="account-monogram" aria-hidden="true">${e(accountData.display_name.slice(0,1).toUpperCase())}</span><div><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</p><h1>${e(accountData.display_name)}</h1><p>@${e(accountData.username)}</p></div></header><div class="account-columns"><section class="account-block"><h2>Ваша коллекция с вами</h2><p>Войдите с этим логином на другом устройстве — вина, заметки и подборки появятся там.</p><div class="account-stats"><span><b>${data.counts.all||0}</b>${word(data.counts.all||0,'вино','вина','вин')}</span><span><b>${data.counts.bottles||0}</b>${word(data.counts.bottles||0,'бутылка','бутылки','бутылок')} дома</span><span><b>${data.lists.length}</b>${word(data.lists.length,'подборка','подборки','подборок')}</span></div><button class="cellar-primary" id="account-to-collection">Открыть коллекцию ↗</button><form id="account-name-form" class="cellar-form"><label>Как к вам обращаться<input name="display_name" maxlength="60" value="${e(accountData.display_name)}" required autocomplete="name"></label><p class="form-error" role="alert" hidden></p><button class="text-button">Сохранить имя</button></form></section><section class="account-block"><h2>Ваши устройства</h2><p>Завершите незнакомую сессию, чтобы отключить доступ к коллекции.</p><div class="session-list">${accountData.sessions.map(s=>`<div><span><strong>${e(s.label)}${s.current?' · это устройство':''}</strong><small>Активность ${date(s.last_seen)}</small></span><button class="text-button" data-session="${e(s.id)}">${s.current?'Выйти':'Отключить'}</button></div>`).join('')}</div><details class="account-security"><summary>Пароль и восстановление</summary><form id="account-password-form" class="cellar-form"><label>Текущий пароль<input type="password" name="current_password" minlength="10" maxlength="256" autocomplete="current-password" required></label><label>Новый пароль<input type="password" name="new_password" minlength="10" maxlength="256" autocomplete="new-password" required></label><p class="field-hint">Другие устройства выйдут из аккаунта. Вы получите новый код восстановления.</p><p class="form-error" role="alert" hidden></p><button class="cellar-primary">Обновить пароль</button></form></details></section></div>`;
   $c('account-password-form').onsubmit=ev=>{ev.preventDefault();busy(ev.submitter,async()=>{const result=await request('account/password',Object.fromEntries(new FormData(ev.target)));await refresh();renderAccount();$c('recovery-code').textContent=result.recovery_code;modal('recovery-dialog');},ev.target);};
   $c('account-to-collection').onclick=()=>showView('collection');$c('account-name-form').onsubmit=ev=>{ev.preventDefault();busy(ev.submitter,async()=>{await request('account/name',{display_name:ev.target.elements.display_name.value});await refresh();renderAccount();notice('Имя сохранено');},ev.target);};root.querySelectorAll('[data-session]').forEach(button=>button.onclick=()=>confirmation(button.textContent==='Выйти'?'Выйти из аккаунта?':'Отключить устройство?','Коллекция останется в аккаунте. Для доступа потребуется войти снова.',async()=>{const session=accountData.sessions.find(s=>s.id===button.dataset.session);await request(session.current?'account/logout':'account/revoke',session.current?{}:{session_id:session.id});if(session.current)await accountChanged();else await refresh();renderAccount();window.scrollTo({top:0,behavior:'instant'});}));return;
  }
  const signup=authMode==='register',recovery=authMode==='recover';root.innerHTML=`<div class="auth-layout"><div class="auth-story"><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</p><h1>Ваша коллекция.<br><em>Всегда с вами.</em></h1><p>Сохраните вина, заметки и подборки — и возвращайтесь к ним с любого устройства.</p><div class="auth-promise"><span>01</span><p>Коллекция сохранится при смене телефона.</p></div><div class="auth-promise"><span>02</span><p>Только ваши оценки, заметки и впечатления.</p></div><div class="auth-promise"><span>03</span><p>Первый скан и сохранения доступны без регистрации.</p></div></div><div class="auth-panel"><div class="auth-tabs"><button data-auth-mode="register" class="${signup?'active':''}">Создать аккаунт</button><button data-auth-mode="login" class="${!signup&&!recovery?'active':''}">Войти</button></div><h2>${signup?'Начните свою историю':recovery?'Восстановить доступ':'С возвращением'}</h2><form id="account-auth-form" class="cellar-form">${signup?'<label>Имя<input name="display_name" maxlength="60" placeholder="Как к вам обращаться" autocomplete="name"></label>':''}<label>Логин<input name="username" minlength="3" maxlength="32" pattern="[a-zA-Z0-9][a-zA-Z0-9_.\\-]{2,31}" placeholder="Например, saveliy" autocomplete="username" autocapitalize="none" spellcheck="false" required></label><p class="field-hint">Латинские буквы, цифры, точка, дефис или подчёркивание.</p>${recovery?'<label>Код восстановления<input name="recovery_code" autocomplete="off" required placeholder="Код, полученный при регистрации"></label>':''}<label>${recovery?'Новый пароль':'Пароль'}<span class="password-field"><input id="account-password" aria-label="${recovery?'Новый пароль':'Пароль'}" type="password" name="password" minlength="10" maxlength="256" autocomplete="${signup||recovery?'new-password':'current-password'}" required placeholder="Не меньше 10 символов"><button type="button" id="toggle-password" aria-label="Показать пароль">Показать</button></span></label>${signup?'<p class="field-hint">Текущие вина и оценки сохранятся в вашем аккаунте. После регистрации выдадим код восстановления.</p>':''}<div id="guest-merge-choice" hidden></div><p class="form-error" role="alert" hidden></p><button class="cellar-primary" type="submit">${signup?'Создать аккаунт':recovery?'Обновить пароль':'Войти'}</button></form><button id="auth-recovery" class="text-button">${recovery?'Вернуться ко входу':'Забыли пароль?'}</button><button id="continue-guest" class="text-button">Продолжить без аккаунта ↗</button></div></div>`;
  root.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{authMode=b.dataset.authMode;authMerge=null;renderAccount();});$c('auth-recovery').onclick=()=>{authMode=recovery?'login':'recover';authMerge=null;renderAccount();};$c('continue-guest').onclick=()=>showView('collection');$c('toggle-password').onclick=()=>{const input=$c('account-password'),visible=input.type==='password';input.type=visible?'text':'password';$c('toggle-password').textContent=visible?'Скрыть':'Показать';$c('toggle-password').setAttribute('aria-label',visible?'Скрыть пароль':'Показать пароль');};$c('account-auth-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target,button=ev.submitter;if(button.disabled)return;button.disabled=true;form.querySelector('.form-error').hidden=true;const body=Object.fromEntries(new FormData(form));if(authMerge){body.merge_guest=body.merge_choice==='merge';body.quantity_policy=body.quantity_policy||'keep';}try{const result=await request('account/'+authMode,body);if(result.sign_in_required){authMode='login';authMerge=null;renderAccount();notice('Пароль обновлён. Войдите с новым паролем.');}else{await accountChanged();renderAccount();window.scrollTo({top:0,behavior:'instant'});}if(result.recovery_code){$c('recovery-code').textContent=result.recovery_code;modal('recovery-dialog');}}catch(error){if(error.detail?.code==='guest_merge'){authMerge=error.detail.summary;showMerge(authMerge);}else errorAt(form,error);}finally{button.disabled=false;}};
 }
 function showMerge(summary){const box=$c('guest-merge-choice');box.hidden=false;box.innerHTML=`<fieldset><legend>В этом браузере уже есть данные</legend><p>${plural(summary.count,'вино','вина','вин')} · ${plural(summary.lists||0,'подборка','подборки','подборок')} · ${plural(summary.scans||0,'скан','скана','сканов')}</p><label class="check-line"><input type="radio" name="merge_choice" value="merge" required><span>Перенести в аккаунт</span></label><label class="check-line"><input type="radio" name="merge_choice" value="keep" required><span>Оставить отдельной гостевой коллекцией</span></label><p class="field-hint">При переносе существующие оценки и заметки аккаунта сохранятся. Вина и подборки гостя добавятся.</p>${summary.conflicts.length?`<div class="merge-conflicts">${summary.conflicts.map(w=>`<p><b>${e(w.name)}</b><br>В аккаунте: ${w.account} · здесь: ${w.guest} бут.</p>`).join('')}</div><label>Количество для совпавших вин<select name="quantity_policy"><option value="keep">Оставить количество аккаунта</option><option value="sum">Сложить количества — это разные бутылки</option></select></label>`:''}</fieldset>`;box.scrollIntoView({block:'nearest',behavior:'smooth'});}
 async function accountChanged(broadcast=true){if(broadcast)try{localStorage.setItem('wine-auth-change',crypto.randomUUID());}catch{}productData={preferences:{},collection:[],recommendations:[]};entries=[];wineCache.clear();currentWine=null;currentResult=null;assistantAttachment=null;chatContext.length=0;lastDish=null;store.set('wine-history',[]);store.set('wine-product',productData);await initializeProduct();await refresh();try{const result=await request('history');entries=result.items.map(x=>({id:x.id,server_id:x.id,created_at:x.created_at, wine:x.wine,no_wine:x.no_wine,thumb:'/api/product/scans/'+encodeURIComponent(x.id)+'/image'}));store.set('wine-history',entries);}catch{}authMerge=null;selectedList=null;}
 for(const id of ['cellar-query','cellar-color'])$c(id).addEventListener(id==='cellar-query'?'input':'change',render);
 $c('cellar-add').onclick=()=>openCatalog();$c('catalog-scan').onclick=()=>{closeAll();showView('scan');};$c('catalog-history').onclick=()=>{closeAll();showView('history');};
 $c('list-create-form').onsubmit=ev=>{ev.preventDefault();const form=ev.target;busy(ev.submitter,async()=>{const value=Object.fromEntries(new FormData(form));const result=await request('collection/lists',value);selectedList=result.id;await refresh();closeDialog($c('list-create-dialog'));form.reset();notice('Коллекция создана. Выберите вина для её заполнения.');},form);};
 $c('copy-recovery').onclick=async()=>{try{await navigator.clipboard.writeText($c('recovery-code').textContent);$c('copy-recovery').textContent='Код скопирован';}catch{notice('Выделите и скопируйте код вручную.');}};
 $c('recovery-dialog').addEventListener('close',()=>{$c('recovery-code').textContent='';$c('copy-recovery').textContent='Скопировать код';});
 window.addEventListener('storage',ev=>{if(ev.key==='wine-auth-change'){closeAll();accountChanged(false).then(()=>{if(currentView==='account')renderAccount();else showView('collection');});}});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&['collection','account'].includes(currentView))refresh().then(()=>{if(currentView==='account')renderAccount();});});
 initPromise.then(refresh);
 async function loadHistory(){if(!accountData.authenticated)return;try{const result=await request('history');const old=new Map(entries.map(x=>[x.server_id,x]));entries=result.items.map(x=>({...old.get(x.id),id:x.id,server_id:x.id,created_at:x.created_at,wine:x.wine,no_wine:x.no_wine,thumb:old.get(x.id)?.thumb||'/api/product/scans/'+encodeURIComponent(x.id)+'/image'}));store.set('wine-history',entries);if(currentView==='history')renderHistory();}catch{}}
 function signIn(mode='login'){authMode=mode;authMerge=null;closeAll();showView('account');}
 return {refresh,render,attach,account,search,openCatalog,loadHistory,signIn};
})();
